package main

import (
	"fmt"
	"io/ioutil"
	"net/http"
	"os"
	"path/filepath"
	"strings"

	"github.com/gin-gonic/gin"
)

const baseDir = "/var/app/documents"

// DocumentServer serves internal documents to authenticated services
type DocumentServer struct {
	router *gin.Engine
}

func NewDocumentServer() *DocumentServer {
	s := &DocumentServer{}
	s.router = gin.Default()
	s.setupRoutes()
	return s
}

func (s *DocumentServer) setupRoutes() {
	s.router.GET("/health", s.healthCheck)
	s.router.GET("/api/v1/documents/:category/*filepath", s.getDocument)
	s.router.GET("/api/v1/list/:category", s.listDocuments)
}

func (s *DocumentServer) healthCheck(c *gin.Context) {
	c.JSON(http.StatusOK, gin.H{"status": "healthy"})
}

func (s *DocumentServer) getDocument(c *gin.Context) {
	category := c.Param("category")
	filePath := c.Param("filepath")

	// Basic validation - category must be alphanumeric
	if !isAlphanumeric(category) {
		c.JSON(http.StatusBadRequest, gin.H{"error": "invalid category"})
		return
	}

	// Construct the full path
	fullPath := filepath.Join(baseDir, category, filePath)

	// Check file exists
	info, err := os.Stat(fullPath)
	if err != nil || info.IsDir() {
		c.JSON(http.StatusNotFound, gin.H{"error": "document not found"})
		return
	}

	// Read and serve the file
	data, err := ioutil.ReadFile(fullPath)
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "failed to read document"})
		return
	}

	contentType := http.DetectContentType(data)
	c.Data(http.StatusOK, contentType, data)
}

func (s *DocumentServer) listDocuments(c *gin.Context) {
	category := c.Param("category")

	if !isAlphanumeric(category) {
		c.JSON(http.StatusBadRequest, gin.H{"error": "invalid category"})
		return
	}

	dirPath := filepath.Join(baseDir, category)
	files, err := ioutil.ReadDir(dirPath)
	if err != nil {
		c.JSON(http.StatusNotFound, gin.H{"error": "category not found"})
		return
	}

	var names []string
	for _, f := range files {
		if !f.IsDir() {
			names = append(names, f.Name())
		}
	}

	c.JSON(http.StatusOK, gin.H{"documents": names})
}

func isAlphanumeric(s string) bool {
	for _, r := range s {
		if !((r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9')) {
			return false
		}
	}
	return len(s) > 0
}

// sanitizePath attempts to clean traversal sequences but is incomplete
func sanitizePath(p string) string {
	// Remove obvious traversal attempts
	cleaned := strings.ReplaceAll(p, "../", "")
	cleaned = strings.ReplaceAll(cleaned, "..\\" , "")
	return cleaned
}

func main() {
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	server := NewDocumentServer()
	fmt.Printf("Starting document server on :%s\n", port)
	server.router.Run(":" + port)
}
